49	/**
50	 * Resolves the requested model alias (e.g., 'auto-gemini-3', 'pro', 'flash', 'flash-lite')
51	 * to a concrete model name.
52	 *
53	 * @param requestedModel The model alias or concrete model name requested by the user.
54	 * @param useGemini3_1 Whether to use Gemini 3.1 Pro Preview for auto/pro aliases.
55	 * @param hasAccessToPreview Whether the user has access to preview models.
56	 * @returns The resolved concrete model name.
57	 */
58	export function resolveModel(
59	  requestedModel: string,
60	  useGemini3_1: boolean = false,
61	  useCustomToolModel: boolean = false,
62	  hasAccessToPreview: boolean = true,
63	): string {
64	  let resolved: string;
65	  switch (requestedModel) {
66	    case PREVIEW_GEMINI_MODEL:
67	    case PREVIEW_GEMINI_MODEL_AUTO:
68	    case GEMINI_MODEL_ALIAS_AUTO:
69	    case GEMINI_MODEL_ALIAS_PRO: {
70	      if (useGemini3_1) {
71	        resolved = useCustomToolModel
72	          ? PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL
73	          : PREVIEW_GEMINI_3_1_MODEL;
74	      } else {
75	        resolved = PREVIEW_GEMINI_MODEL;
76	      }
77	      break;
78	    }
79	    case DEFAULT_GEMINI_MODEL_AUTO: {
80	      resolved = DEFAULT_GEMINI_MODEL;
81	      break;
82	    }
83	    case GEMINI_MODEL_ALIAS_FLASH: {
84	      resolved = PREVIEW_GEMINI_FLASH_MODEL;
85	      break;
86	    }
87	    case GEMINI_MODEL_ALIAS_FLASH_LITE: {
88	      resolved = DEFAULT_GEMINI_FLASH_LITE_MODEL;
89	      break;
90	    }
91	    default: {
92	      resolved = requestedModel;
93	      break;
94	    }
95	  }
96	
97	  if (!hasAccessToPreview && isPreviewModel(resolved)) {
98	    // Downgrade to stable models if user lacks preview access.
99	    switch (resolved) {
100	      case PREVIEW_GEMINI_FLASH_MODEL:
101	        return DEFAULT_GEMINI_FLASH_MODEL;
102	      case PREVIEW_GEMINI_MODEL:
103	      case PREVIEW_GEMINI_3_1_MODEL:
104	      case PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL:
105	        return DEFAULT_GEMINI_MODEL;
106	      default:
107	        // Fallback for unknown preview models, preserving original logic.
108	        if (resolved.includes('flash-lite')) {
109	          return DEFAULT_GEMINI_FLASH_LITE_MODEL;
110	        }
111	        if (resolved.includes('flash')) {
112	          return DEFAULT_GEMINI_FLASH_MODEL;
113	        }
114	        return DEFAULT_GEMINI_MODEL;
115	    }
116	  }
117	
118	  return resolved;
119	}
